llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Mosliciguat, a bis-carboxylic acid with a complex polar structure, had an absolute oral bioavailability of 23.1% in healthy volunteers, directly demonstrating that a dianionic bis-carboxylate can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Bumetanide, a carboxylic acid-containing diuretic, showed absolute oral bioavailability of 79% in elderly subjects, supporting high F for acidic, polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Levodopa, a polar amino acid, showed absolute oral bioavailability of 80.4% in fasted healthy volunteers, indicating that polar/ionizable groups do not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "6-MNA, the carboxylic acid active metabolite of nabumetone, had an absolute oral bioavailability of approximately 35%, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Azosemide, which shares a thiophene-methyl motif, had low oral bioavailability (~10%), providing contradictory evidence; however, its tetrazole/sulfonamide acidity and different absorption profile limit direct transfer to the bis-carboxylate query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High-transfer human absolute bioavailability data, especially from mosliciguat (bis-carboxylate, F=23.1%) and other acidic/polar drugs, outweigh the physicochemical prior and the single azosemide low-F example; F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct human oral bioavailability data for the exact query molecule.",
    "The two-carboxyl dianion may reduce passive permeability, and transporter-mediated absorption is not directly assessed.",
    "Azosemide's low F introduces uncertainty despite structural differences from the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

